class Solution { long sort(long[] a,int l,int r,int lo,int hi){if(r-l<=1)return 0;int m=(l+r)/2;long c=sort(a,l,m,lo,hi)+sort(a,m,r,lo,hi);int i=m,j=m;for(int x=l;x<m;x++){while(i<r&&a[i]-a[x]<lo)i++;while(j<r&&a[j]-a[x]<=hi)j++;c+=j-i;}long[] t=new long[r-l];int x=l,y=m,k=0;while(x<m||y<r)t[k++]=(y==r||(x<m&&a[x]<=a[y]))?a[x++]:a[y++];System.arraycopy(t,0,a,l,t.length);return c;} public int countRangeSum(int[] a,int lo,int hi){long[] p=new long[a.length+1];for(int i=0;i<a.length;i++)p[i+1]=p[i]+a[i];return (int)sort(p,0,p.length,lo,hi);} }
